insert into bwr_private.tasks(app_id,id,label,expected,explanation,fields,hint1,hint2) values('halloween-waffelstand','2.8010.eintraege','8010 SBK – Buchungen im T-Konto','{"r0_side": "Soll", "r0_contra": "2880", "r0_amount": "1.301,50 €", "r1_side": "Soll", "r1_contra": "0700", "r1_amount": "28,00 €", "r2_side": "Haben", "r2_contra": "3000", "r2_amount": "1.329,50 €"}','Abschluss Kasse: Soll, 2880, 1.301,50 €; Abschluss MA: Soll, 0700, 28,00 €; Abschluss EK: Haben, 3000, 1.329,50 €','[{"key": "r0_side", "label": "Abschluss Kasse – Seite", "type": "select", "options": ["Soll", "Haben"]}, {"key": "r0_contra", "label": "Abschluss Kasse – Gegenkonto / AB", "type": "account"}, {"key": "r0_amount", "label": "Abschluss Kasse – Betrag in €", "type": "money"}, {"key": "r1_side", "label": "Abschluss MA – Seite", "type": "select", "options": ["Soll", "Haben"]}, {"key": "r1_contra", "label": "Abschluss MA – Gegenkonto / AB", "type": "account"}, {"key": "r1_amount", "label": "Abschluss MA – Betrag in €", "type": "money"}, {"key": "r2_side", "label": "Abschluss EK – Seite", "type": "select", "options": ["Soll", "Haben"]}, {"key": "r2_contra", "label": "Abschluss EK – Gegenkonto / AB", "type": "account"}, {"key": "r2_amount", "label": "Abschluss EK – Betrag in €", "type": "money"}]','Ordne jedem genannten Vorgang die Kontoseite und das Gegenkonto zu. Den Anfangsbestand kennzeichnest du mit AB.','Aktive Bestandskonten: Anfangsbestand und Zugänge im Soll. Passive Bestandskonten: Anfangsbestand und Zugänge im Haben. Aufwendungen stehen im Soll, Erträge im Haben.'::text) on conflict(app_id,id) do update set label=excluded.label,expected=excluded.expected,explanation=excluded.explanation,fields=excluded.fields,hint1=excluded.hint1,hint2=excluded.hint2;
insert into bwr_private.tasks(app_id,id,label,expected,explanation,fields,hint1,hint2) values('halloween-waffelstand','2.8010.f','8010 SBK · f) Abschlussbuchungssatz bilden','{"closing": "entfällt"}','Entfällt: Das ausgeglichene SBK wird nicht über ein weiteres Konto abgeschlossen.','[{"key": "closing", "label": "Abschlussbuchung", "type": "select", "options": ["Buchungssatz erforderlich", "entfällt"]}]','Der Saldo steht im abzuschließenden Konto auf der kleineren Seite.','Bestimme zuerst die Seite im bisherigen Konto. Die Gegenbuchung erfolgt im Abschlusskonto auf der anderen Seite. Beim SBK entfällt die Buchung.'::text) on conflict(app_id,id) do update set label=excluded.label,expected=excluded.expected,explanation=excluded.explanation,fields=excluded.fields,hint1=excluded.hint1,hint2=excluded.hint2;
insert into bwr_private.tasks(app_id,id,label,expected,explanation,fields,hint1,hint2) values('halloween-waffelstand','2.8010.g','8010 SBK · g) Abschluss buchen und Summen ergänzen','{"soll": "1.329,50 €", "haben": "1.329,50 €"}','Keine zusätzliche Buchung im SBK. Beide Endsummen betragen 1.329,50 €.','[{"key": "soll", "label": "Endsumme Soll in €", "type": "money"}, {"key": "haben", "label": "Endsumme Haben in €", "type": "money"}]','Ergänze den Saldo auf der kleineren Seite. Danach müssen beide Seiten gleich groß sein.','Die Endsumme entspricht auf beiden Seiten der vorher größeren Summe. Beim ausgeglichenen SBK ist keine zusätzliche Saldobuchung nötig.'::text) on conflict(app_id,id) do update set label=excluded.label,expected=excluded.expected,explanation=excluded.explanation,fields=excluded.fields,hint1=excluded.hint1,hint2=excluded.hint2;
