insert into bwr_private.tasks(app_id,id,label,expected,explanation,fields,hint1,hint2) values('halloween-waffelstand','2.8020.c','8020 GUV · c) Saldo berechnen','{"high": "862,50 €", "low": "233,00 €", "saldo": "629,50 €"}','862,50 € − 233,00 € = 629,50 €. Der Gewinn beträgt 629,50 €.','[{"key": "high", "label": "Größere Summe in €", "type": "money"}, {"key": "low", "label": "Kleinere Summe in €", "type": "money"}, {"key": "saldo", "label": "Saldo in €", "type": "money"}]','Der Saldo ist die Differenz zwischen den beiden Kontensummen.','Größere Summe minus kleinere Summe. Sind beide Summen gleich, beträgt die Differenz 0,00 €.'::text) on conflict(app_id,id) do update set label=excluded.label,expected=excluded.expected,explanation=excluded.explanation,fields=excluded.fields,hint1=excluded.hint1,hint2=excluded.hint2;
