insert into bwr_private.tasks(app_id,id,label,expected,explanation,fields,hint1,hint2) values('halloween-waffelstand','2.8020.f','8020 GUV · f) Abschlussbuchungssatz bilden','{"debit": "8020", "credit": "3000", "amount": "629,50 €"}','8020 an 3000 629,50 €. Der Saldo wird im abzuschließenden Konto auf der kleineren Seite eingetragen.','[{"key": "debit", "label": "Sollkonto", "type": "account"}, {"key": "credit", "label": "Habenkonto", "type": "account"}, {"key": "amount", "label": "Saldobetrag in €", "type": "money"}]','Der Saldo steht im abzuschließenden Konto auf der kleineren Seite.','Bestimme zuerst die Seite im bisherigen Konto. Die Gegenbuchung erfolgt im Abschlusskonto auf der anderen Seite. Beim SBK entfällt die Buchung.'::text) on conflict(app_id,id) do update set label=excluded.label,expected=excluded.expected,explanation=excluded.explanation,fields=excluded.fields,hint1=excluded.hint1,hint2=excluded.hint2;
insert into bwr_private.tasks(app_id,id,label,expected,explanation,fields,hint1,hint2) values('halloween-waffelstand','2.8020.g','8020 GUV · g) Abschluss buchen und Summen ergänzen','{"side": "Soll", "contra": "3000", "amount": "629,50 €", "soll": "862,50 €", "haben": "862,50 €"}','Abschluss: Soll, Gegenkonto 3000, 629,50 €. Beide Endsummen betragen 862,50 €.','[{"key": "side", "label": "Abschluss auf der Seite", "type": "select", "options": ["Soll", "Haben"]}, {"key": "contra", "label": "Gegenkonto", "type": "account"}, {"key": "amount", "label": "Abschlussbetrag in €", "type": "money"}, {"key": "soll", "label": "Endsumme Soll in €", "type": "money"}, {"key": "haben", "label": "Endsumme Haben in €", "type": "money"}]','Ergänze den Saldo auf der kleineren Seite. Danach müssen beide Seiten gleich groß sein.','Die Endsumme entspricht auf beiden Seiten der vorher größeren Summe. Beim ausgeglichenen SBK ist keine zusätzliche Saldobuchung nötig.'::text) on conflict(app_id,id) do update set label=excluded.label,expected=excluded.expected,explanation=excluded.explanation,fields=excluded.fields,hint1=excluded.hint1,hint2=excluded.hint2;
create or replace function public.bwr_api(action text,payload jsonb default '{}',session_token text default '') returns jsonb language plpgsql security definer set search_path='' as $$
declare u bwr_private.accounts; target bwr_private.accounts; c bwr_private.classes; ap bwr_private.apps; task bwr_private.tasks; p bwr_private.progress; lim bwr_private.login_limits; r jsonb; items jsonb; tok text; pw text; username text; aid uuid; cid uuid; appkey text; i integer; n integer; v integer; alphabet text:='abcdefghjkmnpqrstuvwxyz23456789'; checks jsonb; given jsonb; correct boolean; all_done boolean; mistakes integer; rid uuid; k text;
begin
 if pg_column_size(payload)>100000 then raise exception 'Anfrage zu groß';end if;
 if action='login' then
  username:=lower(trim(payload->>'login'));pw:=payload->>'password';
  if username is null or length(username)>80 or pw is null or length(pw)>200 then return jsonb_build_object('error','Anmeldung fehlgeschlagen.');end if;
  insert into bwr_private.login_limits(login) values(username) on conflict do nothing;
  select * into lim from bwr_private.login_limits where login=username for update;
  if lim.window_start<now()-interval '15 minutes' then update bwr_private.login_limits set attempts=0,window_start=now() where login=username;lim.attempts:=0;end if;
  if lim.attempts>=5 then return jsonb_build_object('error','Zu viele Anmeldeversuche. Bitte nach 15 Minuten erneut versuchen.');end if;
  update bwr_private.login_limits set attempts=attempts+1 where login=username;
  select * into u from bwr_private.accounts where lower(login)=username;
  if u.id is null then perform extensions.crypt(pw,extensions.gen_salt('bf',10));return jsonb_build_object('error','Account oder Passwort ist falsch.');end if;
  if u.password_hash<>extensions.crypt(case when u.role='student' then lower(pw) else pw end,u.password_hash) then return jsonb_build_object('error','Account oder Passwort ist falsch.');end if;
  update bwr_private.login_limits set attempts=0 where login=username;
  delete from bwr_private.sessions where expires_at<now();
  tok:=encode(extensions.gen_random_bytes(32),'hex');
  insert into bwr_private.sessions values(encode(extensions.digest(tok,'sha256'),'hex'),u.id,now()+interval '8 hours');
  return jsonb_build_object('token',tok);
 end if;
 select a.* into u from bwr_private.accounts a join bwr_private.sessions s on s.account_id=a.id where s.token_hash=encode(extensions.digest(session_token,'sha256'),'hex') and s.expires_at>now();
 if u.id is null then return jsonb_build_object('error','Bitte melde dich erneut an.','expired',true);end if;
 select * into c from bwr_private.classes where id=u.class_id;
 if u.role='teacher' and payload ? 'class_id' then
  select cl.* into c from bwr_private.classes cl join bwr_private.teacher_classes tc on tc.class_id=cl.id where tc.account_id=u.id and cl.id=(payload->>'class_id')::uuid;
  if c.id is null then raise exception 'Kein Zugriff auf diese Klasse';end if;
 end if;
 if action='logout' then delete from bwr_private.sessions where token_hash=encode(extensions.digest(session_token,'sha256'),'hex');return '{}'::jsonb;end if;
 if action='me' then
  select coalesce(jsonb_agg(to_jsonb(a) order by a.title),'[]'::jsonb) into items from bwr_private.apps a join bwr_private.class_apps ca on ca.app_id=a.id where ca.class_id=c.id and a.active and (u.role='teacher' or exists(select 1 from bwr_private.grants g where g.app_id=a.id and g.account_id=u.id and g.enabled));
  return jsonb_build_object('account',jsonb_build_object('id',u.id,'login',u.login,'role',u.role),'class',to_jsonb(c),'apps',items,'tasks',coalesce((select jsonb_agg(jsonb_build_object('app_id',t.app_id,'id',t.id,'label',t.label)) from bwr_private.tasks t where t.app_id in(select el->>'id' from jsonb_array_elements(items) el)),'[]'::jsonb),'progress',coalesce((select jsonb_agg(to_jsonb(x)) from bwr_private.progress x where x.account_id=u.id),'[]'::jsonb));
 end if;
 if action='password' then
  aid:=coalesce((payload->>'account_id')::uuid,u.id);
  select * into target from bwr_private.accounts where id=aid;
  if target.id is null or not(target.id=u.id or (u.role='teacher' and exists(select 1 from bwr_private.teacher_classes tc where tc.account_id=u.id and tc.class_id=target.class_id) and target.role='student')) then raise exception 'Kein Zugriff';end if;
  select encryption_key into k from bwr_private.settings where id;
  return jsonb_build_object('password',extensions.pgp_sym_decrypt(target.password_cipher,k));
 end if;
 if action like 'teacher.%' then
  if u.role<>'teacher' then raise exception 'Kein Zugriff';end if;
  if action='teacher.classes' then return jsonb_build_object('classes',coalesce((select jsonb_agg(to_jsonb(cl) order by cl.label) from bwr_private.classes cl join bwr_private.teacher_classes tc on tc.class_id=cl.id where tc.account_id=u.id),'[]'::jsonb));end if;
  if action='teacher.create_class' then
   username:=trim(payload->>'class_name');n:=(payload->>'year')::integer;
   if username is null or n is null or username !~ '^([5-9]|10)[a-z]$' or n<2020 or n>2100 then raise exception 'Bitte Klasse wie 8b und ein gültiges Jahr eingeben';end if;
   insert into bwr_private.classes(label,class_name,grade,school_year) values(username||n,username,regexp_replace(username,'[a-z]','','g'),n) returning id into cid;
   insert into bwr_private.teacher_classes values(u.id,cid);return jsonb_build_object('id',cid);
  end if;
  if action='teacher.class' then return bwr_private.class_data(c.id);end if;
  if action='teacher.add' then
   n:=(payload->>'count')::integer;if n<1 or n>100 then raise exception 'Bitte 1 bis 100 Accounts wählen';end if;
   select * into c from bwr_private.classes where id=c.id for update;
   for i in 1..n loop
    username:=c.label||bwr_private.suffix(c.next_suffix);c.next_suffix:=c.next_suffix+1;
    loop
     pw:='';for j in 1..4 loop
      loop v:=get_byte(extensions.gen_random_bytes(1),0);exit when v<256-(256%length(alphabet));end loop;
      pw:=pw||substr(alphabet,1+v%length(alphabet),1);
     end loop;
     exit when pw ~ '[a-z]' and pw ~ '[0-9]';
    end loop;
    aid:=bwr_private.add_account(c.id,username,pw);
    insert into bwr_private.grants(account_id,app_id,enabled)
    select aid,ca.app_id,(select count(*) from bwr_private.grants g join bwr_private.accounts a on a.id=g.account_id where a.class_id=c.id and a.role='student' and a.id<>aid and g.app_id=ca.app_id and g.enabled) > (select count(*) from bwr_private.accounts a where a.class_id=c.id and a.role='student' and a.id<>aid)/2.0 from bwr_private.class_apps ca where ca.class_id=c.id;
   end loop;
   update bwr_private.classes set next_suffix=c.next_suffix where id=c.id;return bwr_private.class_data(c.id);
  end if;
  if action='teacher.assign' then
   appkey:=payload->>'app_id';select * into ap from bwr_private.apps where id=appkey and grade=c.grade and active;
   if ap.id is null then raise exception 'Anwendung passt nicht zur Jahrgangsstufe';end if;
   insert into bwr_private.class_apps values(c.id,appkey) on conflict do nothing;
   insert into bwr_private.grants select id,appkey,false from bwr_private.accounts where class_id=c.id and role='student' on conflict do nothing;return bwr_private.class_data(c.id);
  end if;
  if action='teacher.catalog' then return jsonb_build_object('apps',coalesce((select jsonb_agg(to_jsonb(a) order by title) from bwr_private.apps a where grade=c.grade and active),'[]'::jsonb));end if;
  if action='teacher.detach' then
   appkey:=payload->>'app_id';delete from bwr_private.class_apps where class_id=c.id and app_id=appkey;
   delete from bwr_private.grants where app_id=appkey and account_id in(select id from bwr_private.accounts where class_id=c.id);return bwr_private.class_data(c.id);
  end if;
  aid:=(payload->>'account_id')::uuid;appkey:=payload->>'app_id';
  if aid is not null then select * into target from bwr_private.accounts where id=aid and class_id=c.id and role='student';if target.id is null then raise exception 'Kein Zugriff';end if;end if;
  if action='teacher.delete' then
   if aid is null then raise exception 'Account fehlt';end if;
   delete from bwr_private.accounts where id=aid;return bwr_private.class_data(c.id);
  end if;
  if action='teacher.grant' then
   if not exists(select 1 from bwr_private.class_apps where class_id=c.id and app_id=appkey) then raise exception 'Anwendung nicht zugeordnet';end if;
   insert into bwr_private.grants select id,appkey,(payload->>'enabled')::boolean from bwr_private.accounts where class_id=c.id and role='student' and (aid is null or id=aid) on conflict(account_id,app_id) do update set enabled=excluded.enabled;return bwr_private.class_data(c.id);
  end if;
  if action='teacher.reset' then
   if aid is null and appkey is null then raise exception 'Bitte einen Account oder eine Anwendung wählen';end if;
   delete from bwr_private.progress where account_id in(select id from bwr_private.accounts where class_id=c.id and role='student') and (aid is null or account_id=aid) and (appkey is null or app_id=appkey);
   delete from bwr_private.requests where account_id in(select id from bwr_private.accounts where class_id=c.id and role='student') and (aid is null or account_id=aid);return bwr_private.class_data(c.id);
  end if;
  raise exception 'Unbekannte Lehreraktion';
 end if;
 appkey:=payload->>'app_id';
 if not exists(select 1 from bwr_private.apps a where a.id=appkey and a.active and ((u.role='teacher' and a.grade=c.grade) or (exists(select 1 from bwr_private.class_apps ca where ca.app_id=a.id and ca.class_id=c.id) and exists(select 1 from bwr_private.grants g where g.app_id=a.id and g.account_id=u.id and g.enabled)))) then raise exception 'Anwendung nicht freigeschaltet';end if;
 if action='app.tasks' then return jsonb_build_object('tasks',coalesce((select jsonb_agg(jsonb_build_object('id',id,'label',label,'fields',fields) order by id) from bwr_private.tasks where app_id=appkey),'[]'::jsonb));end if;
 if action in ('app.start','app.check','app.repeat','app.solution') then
  if u.role='teacher' then
   if action='app.check' or action='app.solution' then
    select * into task from bwr_private.tasks where app_id=appkey and id=payload->>'task_id';
    if task.id is null then raise exception 'Aufgabe nicht gefunden';end if;
    if action='app.solution' then return jsonb_build_object('expected',case when task.fields is null then to_jsonb(task.expected) else task.expected::jsonb end,'explanation',task.explanation,'test',true);end if;
    if task.fields is null then correct:=lower(trim(payload->>'answer'))=lower(trim(task.expected));checks:='{}';
    else checks:=bwr_private.grade_fields(task.fields,task.expected::jsonb,payload->'answer');select bool_and(value::boolean) into correct from jsonb_each_text(checks);end if;
    return jsonb_build_object('correct',correct,'fields',checks,'explanation',case when correct then task.explanation else task.hint1 end,'hint2',task.hint2,'test',true);
   end if;return jsonb_build_object('test',true);
  end if;
  rid:=(payload->>'request_id')::uuid;if rid is null then raise exception 'Anfragekennung fehlt';end if;
  -- Ein Account wird gesperrt, damit gleichzeitige Prüfanfragen keine Zähler überschreiben.
  perform 1 from bwr_private.accounts where id=u.id for update;
  select response into r from bwr_private.requests where account_id=u.id and request_id=rid;if found then return r;end if;
  insert into bwr_private.progress(account_id,app_id,started_at,updated_at) values(u.id,appkey,now(),now()) on conflict do nothing;
  select * into p from bwr_private.progress where account_id=u.id and app_id=appkey for update;
  r:='{}'::jsonb;
  if action='app.repeat' then
   if not p.run_complete then raise exception 'Der aktuelle Durchlauf ist noch nicht abgeschlossen';end if;
   p.answers:='{}';p.solved:='{}';p.run_errors:='{}';p.run_solutions:='{}';p.run_complete:=false;
  elsif action in ('app.check','app.solution') then
   select * into task from bwr_private.tasks where app_id=appkey and id=payload->>'task_id';if task.id is null then raise exception 'Aufgabe nicht gefunden';end if;
   if action='app.solution' then
    if coalesce((p.run_errors->>task.id)::integer,0)<3 then raise exception 'Die Musterlösung ist erst nach drei Fehlversuchen in diesem Durchlauf verfügbar.';end if;
    if not coalesce((p.run_solutions->>task.id)::boolean,false) then p.solutions:=p.solutions||jsonb_build_object(task.id,coalesce((p.solutions->>task.id)::integer,0)+1);end if;
    p.run_solutions:=p.run_solutions||jsonb_build_object(task.id,true);
    r:=jsonb_build_object('expected',case when task.fields is null then to_jsonb(task.expected) else task.expected::jsonb end,'explanation',task.explanation);
   else
    if p.run_complete then raise exception 'Bitte zuerst einen neuen Durchlauf starten';end if;
    if length(trim(coalesce(payload->>'answer','')))=0 then raise exception 'Bitte eine Antwort eingeben';end if;
    if task.fields is null then correct:=lower(trim(payload->>'answer'))=lower(trim(task.expected));checks:='{}';given:=to_jsonb(payload->>'answer');
    else given:=payload->'answer';checks:=bwr_private.grade_fields(task.fields,task.expected::jsonb,given);select bool_and(value::boolean) into correct from jsonb_each_text(checks);end if;
    p.answers:=p.answers||jsonb_build_object(task.id,given);
    if correct then p.solved:=p.solved||jsonb_build_object(task.id,true);
    else p.solved:=p.solved-task.id;p.errors:=p.errors||jsonb_build_object(task.id,coalesce((p.errors->>task.id)::integer,0)+1);p.run_errors:=p.run_errors||jsonb_build_object(task.id,coalesce((p.run_errors->>task.id)::integer,0)+1);end if;
    select count(*)>0 and bool_and(coalesce((p.solved->>t.id)::boolean,false)) into all_done from bwr_private.tasks t where t.app_id=appkey;
    if all_done then p.completed_runs:=p.completed_runs+1;p.run_complete:=true;end if;
    mistakes:=coalesce((p.run_errors->>task.id)::integer,0);r:=jsonb_build_object('correct',correct,'fields',checks,'solution_available',mistakes>=3,'explanation',case when correct then task.explanation when mistakes=1 then task.hint1 else task.hint2 end);
   end if;
  end if;
  update bwr_private.progress set answers=p.answers,solved=p.solved,errors=p.errors,run_errors=p.run_errors,solutions=p.solutions,run_solutions=p.run_solutions,completed_runs=p.completed_runs,run_complete=p.run_complete,updated_at=now() where account_id=u.id and app_id=appkey returning * into p;
  r:=r||jsonb_build_object('progress',to_jsonb(p));insert into bwr_private.requests values(u.id,rid,r);return r;
 end if;
 raise exception 'Unbekannte Aktion';
end$$;
-- Diese Prüfungen laufen mit temporären Testdaten in derselben Transaktion.
savepoint halloween_pruefung;
do $$
declare cid uuid;sid uuid;tid uuid;tok text;ttok text;r jsonb;z jsonb;expected jsonb;taskrow bwr_private.tasks;n integer;i integer;request_id uuid;
begin
 if (select count(*) from bwr_private.tasks where app_id='halloween-waffelstand')<>72 then raise exception 'Erwartet: 72 Prüfgruppen';end if;
 if bwr_private.normalized('1.301,50 €','money')::numeric<>1301.50 then raise exception 'Deutsches Zahlenformat fehlerhaft';end if;
 if bwr_private.normalized('28','money')::numeric<>28 or bwr_private.normalized('28.00','money')::numeric<>28 then raise exception 'Zahlenvarianten fehlerhaft';end if;
 if bwr_private.normalized('0700 MA','account')<>'0700' then raise exception 'Kontenformat fehlerhaft';end if;
 if bwr_private.normalized('1.30.1,50','money') is not null then raise exception 'Ungültige Zahl akzeptiert';end if;
 insert into bwr_private.classes(label,class_name,grade,school_year) values('halloween-pruefung-'||gen_random_uuid(),'8x','8',2026) returning id into cid;
 sid:=bwr_private.add_account(cid,'halloween-student-'||cid,'a2b3');tid:=bwr_private.add_account(cid,'halloween-teacher-'||cid,'TemporarilyOnly98','teacher');
 insert into bwr_private.teacher_classes values(tid,cid);
 insert into bwr_private.class_apps values(cid,'halloween-waffelstand');insert into bwr_private.grants values(sid,'halloween-waffelstand',true);
 tok:=public.bwr_api('login',jsonb_build_object('login','halloween-student-'||cid,'password','A2B3'))->>'token';
 ttok:=public.bwr_api('login',jsonb_build_object('login','halloween-teacher-'||cid,'password','TemporarilyOnly98'))->>'token';
 if tok is null or ttok is null then raise exception 'Testanmeldung fehlgeschlagen';end if;
 r:=public.bwr_api('app.start',jsonb_build_object('app_id','halloween-waffelstand','request_id',gen_random_uuid()),tok);
 begin perform public.bwr_api('app.solution',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','request_id',gen_random_uuid()),tok);raise exception 'TEST: Lösung zu früh freigegeben';exception when raise_exception then if sqlerrm like 'TEST:%' then raise;end if;end;
 for i in 1..3 loop
  request_id:=gen_random_uuid();
  r:=public.bwr_api('app.check',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','answer',jsonb_build_object('amount','1'),'request_id',request_id),tok);
  z:=public.bwr_api('app.check',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','answer',jsonb_build_object('amount','1'),'request_id',request_id),tok);
  if z<>r then raise exception 'Doppelte Anfrage liefert abweichendes Ergebnis';end if;
  if (r#>>'{progress,run_errors,1.1.betrag}')::integer<>i then raise exception 'Fehlversuch doppelt oder falsch gezählt';end if;
  if i<3 then
   begin perform public.bwr_api('app.solution',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','request_id',gen_random_uuid()),tok);raise exception 'TEST: Lösung vor drei Fehlern verfügbar';exception when raise_exception then if sqlerrm like 'TEST:%' then raise;end if;end;
  end if;
 end loop;
 r:=public.bwr_api('app.solution',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','request_id',gen_random_uuid()),tok);
 r:=public.bwr_api('app.solution',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','request_id',gen_random_uuid()),tok);
 if r#>>'{progress,solutions,1.1.betrag}'<>'1' then raise exception 'Lösungshilfe wird mehrfach pro Durchlauf gezählt';end if;
 if coalesce((r#>>'{progress,solved,1.1.betrag}')::boolean,false) then raise exception 'Lösungsanzeige löst Aufgabe automatisch';end if;
 begin perform public.bwr_api('app.check',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','answer','{}'::jsonb,'request_id',gen_random_uuid()),tok);raise exception 'TEST: Leere Eingabe als Versuch akzeptiert';exception when raise_exception then if sqlerrm like 'TEST:%' then raise;end if;end;
 for taskrow in select * from bwr_private.tasks where app_id='halloween-waffelstand' order by id loop
  expected:=taskrow.expected::jsonb;
  r:=public.bwr_api('app.check',jsonb_build_object('app_id','halloween-waffelstand','task_id',taskrow.id,'answer',expected,'request_id',gen_random_uuid()),tok);
  if not (r->>'correct')::boolean then raise exception 'Musterlösung nicht erkannt: %',taskrow.id;end if;
 end loop;
 if r#>>'{progress,completed_runs}'<>'1' then raise exception 'Vollständiger Durchlauf nicht erkannt';end if;
 r:=public.bwr_api('app.repeat',jsonb_build_object('app_id','halloween-waffelstand','request_id',gen_random_uuid()),tok);
 if r#>>'{progress,errors,1.1.betrag}'<>'3' then raise exception 'Gesamtfehler bei Wiederholung gelöscht';end if;
 if r#>'{progress,run_errors}'<>'{}'::jsonb then raise exception 'Fehler des Durchlaufs nicht zurückgesetzt';end if;
 begin perform public.bwr_api('app.solution',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','request_id',gen_random_uuid()),tok);raise exception 'TEST: Lösung bleibt bei Wiederholung freigeschaltet';exception when raise_exception then if sqlerrm like 'TEST:%' then raise;end if;end;
 r:=public.bwr_api('app.check',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag','answer',jsonb_build_object('amount','28')),ttok);
 r:=public.bwr_api('app.solution',jsonb_build_object('app_id','halloween-waffelstand','task_id','1.1.betrag'),ttok);
 if exists(select 1 from bwr_private.progress where account_id=tid) then raise exception 'Lehrertest speichert Statistik';end if;
 raise notice 'Halloween-Prüfungen bestanden; Testdaten werden verworfen.';
end $$;
rollback to savepoint halloween_pruefung;

revoke all on all functions in schema bwr_private from public,anon,authenticated;
revoke all on function public.bwr_api(text,jsonb,text) from public;
grant execute on function public.bwr_api(text,jsonb,text) to anon,authenticated;
commit;
-- Erfolgsanzeige:
select count(*) as pruefgruppen from bwr_private.tasks where app_id='halloween-waffelstand';
